module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);
parameter [2:0] A = 3'b000, B = 3'b001, C = 3'b010, D = 3'b011;

  reg [2:0] state;
  reg [2:0] next_state;

  always @(posedge clk) begin
    if (resetn == 1'b0) begin
      state <= A;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      A: begin
        if (r[0] == 1'b1) begin
          next_state = B;
        end else if (r[1] == 1'b1) begin
          next_state = C;
        end else if (r[2] == 1'b1) begin
          next_state = D;
        end else begin
          next_state = A;
        end
      end
      B: begin
        if (r[0] == 1'b1) begin
          next_state = B;
        end else begin
          next_state = A;
        end
      end
      C: begin
        if (r[2] == 1'b1) begin
          next_state = C;
        end else begin
          next_state = A;
        end
      end
      D: begin
        next_state = A;
      end
    endcase
  end

  assign g[0] = (state == A) ? 1'b0 : 1'b1;
  assign g[1] = (state == A) ? 1'b0 : 1'b1;
  assign g[2] = (state == A) ? 1'b0 : 1'b1;

endmodule

