module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
logic   [19:0]   counter50;
        logic   [19:0]   counter72;

        always_ff @ (posedge clk50)
        begin
            if (counter50[19] == 1'b1)
                counter50 <= 20'd0;
            else
                counter50 <= counter50 + 20'd1;
        end

        always_ff @ (posedge clk72)
        begin
            if (counter72[19] == 1'b1)
                counter72 <= 20'd0;
            else
                counter72 <= counter72 + 20'd1;
        end

        assign led[0] = counter50[19];
        assign led[1] = counter50[18];

        assign pmod[7:0] = counter72[19:12];

endmodule

module alu(
    input var [32:0]in_a,
    input var [32:0]in_b,
    input var [4:0]alu_op,

    output [31:0]rd_val_out,
    output lt,
    output ltu,
    output eq
    );
wire [31:0]two_complement;
    wire [31:0]add;
    wire [31:0]and;
    wire [31:0]or;
    wire [31:0]xor;
    wire [31:0]lui;
    wire [31:0]sub;
    wire [31:0]slt;
    wire [31:0]slt_u;
    wire [31:0]eq;
    wire [31:0]lt;
    wire [31:0]ltu;

    assign two_complement = ~in_b + 1;
    assign add = in_a + two_complement;
    assign and = in_a & in_b;
    assign or = in_a | in_b;
    assign xor = in_a ^ in_b;
    assign lui = in_a + 1;
    assign sub = in_a - two_complement;
    assign slt = in_a < in_b;
    assign slt_u = in_a < two_complement;
    assign eq = in_a == in_b;
    assign lt = in_a < two_complement;
    assign ltu = in_a < in_b;

    always_comb begin
        case(alu_op)
            5'b00000: rd_val_out = add;
            5'b00001: rd_val_out = and;
            5'b00010: rd_val_out = or;
            5'b00011: rd_val_out = xor;
            5'b00100: rd_val_out = lui;
            5'b00101: rd_val_out = sub;
            5'b00110: rd_val_out = slt;
            5'b00111: rd_val_out = slt_u;
            5'b01000: rd_val_out = eq;
            5'b01001: rd_val_out = lt;
            5'b01010: rd_val_out = ltu;
            default: rd_val_out = 32'h0;
        endcase
    end

endmodule

module addmuladd_2_stage_signed_16_bit(
	input signed [15:0] a,
	input signed [15:0] b,
	input signed [15:0] c,
	input signed [15:0] d,
	output [15:0] out,
	input clk);
logic signed [31:0] stage0;
	logic signed [31:0] stage1;

	always @(posedge clk) begin
	stage0 <= ((d + a) * b) + c;
	stage1 <= stage0;
	end

	assign out = stage1;
endmodule

