module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
reg [9:0] keypress_array [0:15] = {10'd1, 10'd2, 10'd3, 10'd4, 10'd5, 10'd6, 10'd7, 10'd8, 10'd9, 10'd10, 10'd11, 10'd12, 10'd13, 10'd14, 10'd15};
reg [9:0] keypress_index = 0;
reg [9:0] keypress_delay = 0;
reg [9:0] keypress_counter = 0;
always @(posedge clk) begin
    if (reset) begin
        keypress_index <= 0;
        keypress_delay <= 0;
        keypress_counter <= 0;
    end
    else begin
        if (keypress_counter == 20) begin
            keypress_index <= keypress_index + 1;
            keypress_counter <= 0;
        end
        else begin
            keypress_counter <= keypress_counter + 1;
        end
        if (keypress_index == 15) begin
            keypress_index <= 0;
        end
        if (keypress_counter == 20) begin
            keypress_delay <= keypress_delay + 1;
        end
        if (keypress_delay == 20) begin
            keypress <= keypress_array[keypress_index];
            keypress_delay <= 0;
        end
    end
end
endmodule

