module tone(
    input CLK,
    input[31:0] period, 
    output reg tone_out
    );
parameter CLK_F = 32;
    reg[31:0] prescaler;
    reg[31:0] main_counter;
    always @(posedge CLK) begin
        if(prescaler == 0) begin
            prescaler <= CLK_F - 1;
            main_counter <= 0;
        end
        else begin
            prescaler <= prescaler - 1;
            main_counter <= main_counter + 1;
        end
    end
    always @(posedge CLK) begin
        if(main_counter == period) begin
            tone_out <= ~tone_out;
            main_counter <= 0;
        end
    end
endmodule

module upcounter (Resetn, Clock, E, Q);
    input Resetn, Clock, E;
    output reg [2:0] Q;
always @(posedge Clock, negedge Resetn)
    begin
        if(Resetn == 1'b0)
            Q <= 3'b000;
        else if(E == 1'b1)
            Q <= Q + 1;
    end
endmodule

