module clk_div(
input wire clk_i,
output reg clk_o,
output wire [1:0] count_o
); 

reg [1:0] count;
  always @(posedge clk_i) begin
    if(count == 3'b11) begin
      count <= 3'b00;
    end else begin
      count <= count + 1;
    end
  end
  assign clk_o = (count == 3'b01) ? 1'b1 : 1'b0;
  assign count_o = count;
endmodule

