module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;

reg [1:0] state;

always @ (posedge clk or posedge reset) begin
    if (reset) begin
        state <= 2'b00;
        data_p1 <= 8'b0;
        data_p2 <= 8'b0;
    end else begin
        case (state)
            2'b00: begin
                if (s_valid && s_ready) begin
                    data_p1 <= s_data;
                    state <= 2'b01;
                end
            end
            2'b01: begin
                if (m_ready) begin
                    data_p2 <= data_p1;
                    state <= 2'b10;
                end
            end
            2'b10: begin
                if (s_valid && s_ready) begin
                    data_p1 <= s_data;
                    state <= 2'b01;
                end
            end
            default: begin
                state <= 2'b00;
            end
        endcase
    end
end

assign s_ready = 1'b0;
assign m_data = data_p2;
assign m_valid = 1'b0;

endmodule

