module shift_16_9 (
    input [15:0] x,
    input [15:0] y,
    input [1:0] shiftAlufn,
    output reg [15:0] shiftOut
  );
always @* begin
    case(shiftAlufn)
      2'b00: shiftOut = {16{1'b0}};
      2'b01: shiftOut = {16{1'b0}};
      2'b10: shiftOut = {16{1'b0}};
      2'b11: shiftOut = {16{1'b0}};
      default: shiftOut = {16{1'b0}};
    endcase
  end
  reg [15:0] temp;
  always @* begin
    temp = x;
    case(shiftAlufn)
      2'b00: temp = {16{1'b0}};
      2'b01: temp = {16{1'b0}};
      2'b10: temp = {16{1'b0}};
      2'b11: temp = {16{1'b0}};
      default: temp = {16{1'b0}};
    endcase
    if(shiftAlufn == 2'b00) begin
      shiftOut = temp;
    end
    else if(shiftAlufn == 2'b01) begin
      shiftOut = {16{1'b0}};
    end
    else if(shiftAlufn == 2'b10) begin
      shiftOut = {16{1'b0}};
    end
    else if(shiftAlufn == 2'b11) begin
      shiftOut = {16{1'b0}};
    end
    else begin
      shiftOut = {16{1'b0}};
    end
  end
endmodule

