	case (funct3)
		000: jmpb = (data_rs1 == data_rs2);
		001: jmpb = (data_rs1 != data_rs2);
		100: jmpb = (data_rs1 < data_rs2);
		101: jmpb = (data_rs1 > data_rs2);
		110: jmpb = (data_rs1 <= data_rs2);
		111: jmpb = (data_rs1 >= data_rs2);
		default: jmpb = 1'b0;
	endcase
end

endmodule

