module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  wire io_ready;
  wire tx;

  always @(posedge clock) begin
    if (reset) begin
      state <= 4'b0000;
      data <= 8'b00000000;
    end else begin
      if (tick) begin
        case (state)
          4'b0000: begin
            if (io_valid) begin
              data <= io_bits;
              state <= 4'b0001;
            end
          end
          4'b0001: begin
            tx <= data[0];
            data <= data >> 1;
            if (data[0] == 1'b1) begin
              state <= 4'b0010;
            end else begin
              state <= 4'b0000;
            end
          end
          4'b0010: begin
            tx <= 1'b0;
            state <= 4'b0000;
          end
          default: begin
            state <= 4'b0000;
          end
        endcase
      end
    end
  end

  assign io_ready = (state == 4'b0000) && (data[0] == 1'b0);
endmodule

