    input [3:0] led1, led2, led3, led4, led5, led6,
    output reg sa, sb, sc, sd, se, sf, sg,
    output reg display1, display2, display3, display4, display5, display6
    );
reg [2:0] select;
    always @(posedge clk) begin
        select <= select + 1;
    end
