    assign display2 = select == 3'b001 ? 1'b1 : 1'b0;
    assign display3 = select == 3'b010 ? 1'b1 : 1'b0;
    assign display4 = select == 3'b011 ? 1'b1 : 1'b0;
    assign display5 = select == 3'b100 ? 1'b1 : 1'b0;
    assign display6 = select == 3'b101 ? 1'b1 : 1'b0;
