module tx_add_preamble(
input wire clk,
input wire data_valid_in,
input wire [7:0] data_in,
output reg data_valid_out,
output reg [7:0] data_out
); 

reg [63:0] delay_data;
reg [7:0] delay_data_valid;
always @(posedge clk) begin
    if(data_valid_in) begin
        delay_data_valid[7:0] <= {delay_data_valid[6:0], 1'b0};
        delay_data[7:0] <= {delay_data[6:0], data_in};
    end else begin
        delay_data_valid[7:0] <= {delay_data_valid[6:0], 1'b0};
        delay_data[7:0] <= {delay_data[6:0], 8'b00000000};
    end
end
always @(posedge clk) begin
    if(delay_data_valid[7:0] == 8'b11111111) begin
        data_valid_out <= 1'b1;
        data_out <= delay_data[7:0];
    end else if(delay_data_valid[7:0] == 8'b11111110) begin
        data_valid_out <= 1'b1;
        data_out <= 8'b11010101;
    end else if(delay_data_valid[7:0] == 8'b11111101) begin
        data_valid_out <= 1'b1;
        data_out <= 8'b01010101;
    end else begin
        data_valid_out <= 1'b0;
        data_out <= 8'b00000000;
    end
end
endmodule

