module rbw_check(
    input wire          clk,        
    input wire          a_rst,      
    input wire          i_rbw,      
    input wire[L:0]     i_rbw_adr,  
    input wire          rs,         
    input wire          r_ts,       
    input wire[L:0]     rs_adr,     
    input wire          ws,         
    input wire          w_ts,       
    input wire[L:0]     ws_adr,     
    output wire         o_rbw       
);
reg [L:0]   rbw_adr;
reg         rbw_exists;
reg         rbw_valid;
reg         rbw_ready;
reg         rbw_conflict;

always @(posedge clk or negedge a_rst) begin
    if (!a_rst) begin
        rbw_adr <= 0;
        rbw_exists <= 0;
        rbw_valid <= 0;
        rbw_ready <= 0;
        rbw_conflict <= 0;
    end else begin
        if (i_rbw) begin
            rbw_adr <= i_rbw_adr;
            rbw_exists <= 1;
            rbw_valid <= 0;
            rbw_ready <= 0;
            rbw_conflict <= 0;
        end else if (rs) begin
            if (rs_adr == rbw_adr) begin
                if (rs_adr == ws_adr && r_ts == w_ts) begin
                    rbw_conflict <= 1;
                end else begin
                    rbw_conflict <= 0;
                end
            end else begin
                rbw_conflict <= 0;
            end
        end else if (ws) begin
            if (ws_adr == rbw_adr) begin
                if (ws_adr == rs_adr && w_ts == r_ts) begin
                    rbw_conflict <= 1;
                end else begin
                    rbw_conflict <= 0;
                end
            end else begin
                rbw_conflict <= 0;
            end
        end else begin
            rbw_conflict <= 0;
        end
        if (rbw_conflict == 0) begin
            rbw_valid <= 1;
            rbw_ready <= 1;
        end
    end
end

assign o_rbw = rbw_valid & rbw_ready;

endmodule

