module radix2(
		input wire [1:0] state,
		input wire signed [23:0] din_a_r,
		input wire signed [23:0] din_a_i,
		input wire signed [23:0] din_b_r,
		input wire signed [23:0] din_b_i,
		input wire signed [23:0] w_r,
		input wire signed [23:0] w_i,
		output reg signed[23:0] op_r,
		output reg signed[23:0] op_i,
		output reg signed[23:0] delay_r,
		output reg signed[23:0] delay_i,
		output reg outvalid
	);
reg [41:0] reg_a_r;
	reg [41:0] reg_a_i;
	reg [41:0] reg_b_r;
	reg [41:0] reg_b_i;
	reg [41:0] reg_w_r;
	reg [41:0] reg_w_i;
	reg [41:0] reg_delay_r;
	reg [41:0] reg_delay_i;
	always @(posedge state) begin
		case(state)
			2'b00: begin
				reg_a_r <= din_a_r;
				reg_a_i <= din_a_i;
				reg_b_r <= din_b_r;
				reg_b_i <= din_b_i;
				reg_w_r <= w_r;
				reg_w_i <= w_i;
				reg_delay_r <= 0;
				reg_delay_i <= 0;
				outvalid <= 0;
			end
			2'b01: begin
				reg_a_r <= reg_a_r + reg_b_r;
				reg_a_i <= reg_a_i + reg_b_i;
				reg_b_r <= reg_a_r - reg_b_r;
				reg_b_i <= reg_a_i - reg_b_i;
				outvalid <= 0;
			end
			2'b10: begin
				reg_a_r <= reg_a_r * reg_w_r;
				reg_a_i <= reg_a_i * reg_w_i;
				reg_b_r <= reg_b_r * reg_w_r;
				reg_b_i <= reg_b_i * reg_w_i;
				outvalid <= 0;
			end
			default: begin
				reg_a_r <= 0;
				reg_a_i <= 0;
				reg_b_r <= 0;
				reg_b_i <= 0;
				reg_w_r <= 0;
				reg_w_i <= 0;
				reg_delay_r <= 0;
				reg_delay_i <= 0;
				outvalid <= 0;
			end
		endcase
	end
	always @(posedge outvalid) begin
		op_r <= reg_a_r;
		op_i <= reg_a_i;
		delay_r <= reg_b_r;
		delay_i <= reg_b_i;
	end
endmodule

