module Mapper66(input clk, input ce, input reset,
                input [31:0] flags,
                input [15:0] prg_ain, output [21:0] prg_aout,
                input prg_read, prg_write,                   
                input [7:0] prg_din,
                output prg_allow,                            
                input [13:0] chr_ain, output [21:0] chr_aout,
                output chr_allow,                      
                output vram_a10,                             
                output vram_ce);
reg [3:0] prg_bank, chr_bank;
reg [1:0] prg_allow, chr_allow;
reg vram_ce, vram_a10;

always @(posedge clk) begin
    if (reset) begin
        prg_bank <= 4'b0000;
        chr_bank <= 2'b00;
        vram_ce <= 1'b0;
        vram_a10 <= 1'b0;
    end else begin
        if (prg_write) begin
            if (flags[15]) begin
                prg_bank <= prg_din;
            end else begin
                prg_bank <= 4'b0000;
            end
        end
        if (flags[14]) begin
            vram_ce <= 1'b1;
        end else begin
            vram_ce <= 1'b0;
        end
        if (flags[13]) begin
            vram_a10 <= 1'b1;
        end else begin
            vram_a10 <= 1'b0;
        end
        if (flags[12]) begin
            chr_bank <= 2'b01;
        end else begin
            chr_bank <= 2'b00;
        end
        if (flags[11]) begin
            prg_allow <= 2'b01;
        end else begin
            prg_allow <= 2'b00;
        end
        if (flags[10]) begin
            chr_allow <= 2'b01;
        end else begin
            chr_allow <= 2'b00;
        end
    end
end

assign prg_aout = prg_ain + (prg_bank << 16);
assign chr_aout = chr_ain + (chr_bank << 16);
assign vram_ce = vram_ce;
assign vram_a10 = vram_a10;
assign prg_allow = prg_allow;
assign chr_allow = chr_allow;
endmodule

