module alu
  (
   alu_src1,
   alu_src2,
   alu_opcode,
   minus_is_zero,
   less_than,
   less_than_unsigned,
   alu_result
   );
input wire [31:0]       alu_src1;
   input wire [31:0]	   alu_src2;
   input wire [3:0]	   alu_opcode;
   output reg [31:0]	   alu_result;
   output reg		   minus_is_zero;
   output reg		   less_than;
   output reg		   less_than_unsigned;
reg [32:0]		   internal_result;
   always @ (alu_src1, alu_src2, alu_opcode)
   begin
      case (alu_opcode)
         4'h0: begin
            alu_result = alu_src1 + alu_src2;
         end
         4'h1: begin
            alu_result = alu_src1 - alu_src2;
         end
         4'h2: begin
            alu_result = alu_src1 | alu_src2;
         end
         4'h3: begin
            alu_result = alu_src1 & alu_src2;
         end
         4'h4: begin
            alu_result = alu_src1 ^ alu_src2;
         end
         4'h5: begin
            alu_result = alu_src1 << 1;
         end
         4'h6: begin
            alu_result = alu_src1 >> 1;
         end
         4'h7: begin
            alu_result = alu_src1 << 32;
         end
         4'h8: begin
            alu_result = alu_src1 >> 32;
         end
         4'h9: begin
            internal_result = alu_src1 - alu_src2;
            minus_is_zero = (internal_result[31] == 1'b1) ? 1'b1 : 1'b0;
            less_than = (internal_result[31] == 1'b1) ? 1'b0 : 1'b1;
            less_than_unsigned = (internal_result[31] == 1'b1) ? 1'b1 : 1'b0;
         end
         default: begin
            alu_result = 32'h0;
         end
      endcase
   end
endmodule

