module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
reg [DATA_BITS-1:0] mem[0:15];
reg [DEPTH_BITS-1:0] index;
reg empty;
reg full;

always @(posedge clk) begin
    if (aclr) begin
        empty <= 1'b1;
        full  <= 1'b0;
        index <= 0;
    end else begin
        if (write) begin
            mem[index] <= din;
            index <= index + 1;
            if (index == (1 << DEPTH_BITS) - 1) begin
                full <= 1'b1;
            end else begin
                full <= 1'b0;
            end
        end
        if (read) begin
            if (index == 0) begin
                empty <= 1'b1;
            end else begin
                empty <= 1'b0;
            end
            index <= index - 1;
        end
    end
end

assign dout = mem[index];
assign empty_n = empty;
assign full_n = full;

endmodule

