module pwm(
input wire clk,
input wire rst,
input wire [31:0] duty,
output reg pwm_out
); 

parameter PERIOD = 8;
reg [31:0] duty_reg;
reg counter;
always @(posedge clk) begin
    if(rst) begin
      duty_reg <= duty;
      counter <= 0;
      pwm_out <= 0;
    end else begin
      if(counter < duty_reg) begin
        pwm_out <= 1;
        counter <= counter + 1;
      end else begin
        pwm_out <= 0;
        counter <= 0;
        duty_reg <= duty;
      end
    end
  end
endmodule

