  reg [ACCUM_WIDTH-1:0] ad_reg, m_reg, p_reg;
  wire [ACCUM_WIDTH-1:0] sample_out_reg;

  always @(posedge clk) begin
    if (reset) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end else if (sample_in_stb) begin
      a_reg <= sample_in_a;
      b_reg <= sample_in_b;
    end
  end

  always @(posedge clk) begin
    if (clear) begin
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end else if (sample_in_stb) begin
      ad_reg <= a_reg + b_reg;
    end
  end

  always @(posedge clk) begin
    if (clear) begin
      m_reg <= 0;
    end else if (coeff_load_stb) begin
      m_reg <= ad_reg * coeff_in;
    end
  end

  always @(posedge clk) begin
    if (clear) begin
      p_reg <= 0;
    end else if (coeff_load_stb) begin
      p_reg <= p_reg + m_reg;
    end
  end

  assign sample_out_reg = p_reg[OUT_WIDTH-1:0];
  assign sample_out = sample_out_reg[OUT_WIDTH-1:0];
  assign sample_forward = p_reg[OUT_WIDTH-1:0];
  assign coeff_forward = m_reg[OUT_WIDTH-1:0];

endmodule

