module Control(
   
	input wire clk,rst,
	input [7:0] in3,in2,in1,in0,
	output reg [3:0] anodo,
	output reg [7:0] catodo
    );
localparam N=18;
reg [16:0] q_reg;
always @(posedge clk, posedge rst)
begin
	if(rst)
		q_reg <= 17'b00000000000000000;
	else
		q_reg <= q_reg + 1'b1;
end
assign anodo = {q_reg[15:13],q_reg[12:10],q_reg[9:7],q_reg[6:4],q_reg[3:1],q_reg[0]};
assign catodo = {in3[7:5],in2[7:5],in1[7:5],in0[7:5]};
endmodule

