endmodule

module ASYNC_ROM(q, addr);

  input  [AWIDTH-1:0] addr; 
  output [DWIDTH-1:0] q;
parameter [31:0] DWIDTH = 16;
  parameter [31:0] AWIDTH = 16;
  parameter [31:0] DEPTH = 2**AWIDTH;
  parameter [31:0] MIF_HEX = 0;
  parameter [31:0] MIF_BIN = 0;

  reg [DWIDTH-1:0] mem [0:DEPTH-1];

  initial begin
    for (int i = 0; i < DEPTH; i = i + 1) begin
      if (MIF_HEX == 1) begin
        mem[i] = $readmemh("ROM.hex", i);
      end
      else if (MIF_BIN == 1) begin
        mem[i] = $readmemh("ROM.bin", i);
      end
      else begin
        mem[i] = 0;
      end
    end
  end

  assign q = mem[addr];

endmodule

