module minimal_modelb_rom_set (
    input            clk,
    input [17:0]     addr,
    output reg [7:0] data
);
reg [15:0] mem1 [0:16383];
    reg [15:0] mem2 [0:16383];
    reg [15:0] mem3 [0:16383];

    initial begin
        $readmemh("data1.dat", mem1);
        $readmemh("data2.dat", mem2);
        $readmemh("data3.dat", mem3);
    end

    always @(posedge clk) begin
        case (addr[15:12])
            4'b0000: data <= mem1[addr[11:0]];
            4'b0001: data <= mem2[addr[11:0]];
            4'b0010: data <= mem3[addr[11:0]];
            default: data <= 8'b00000000;
        endcase
    end

endmodule

