module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);
reg [DATA_WIDTH-1:0] shift_reg;
    wire [DATA_WIDTH-1:0] shift_out;

    if (DATA_TYPE == "signed") begin
        if (ASYNC == 0) begin
            always @(posedge clk) begin
                shift_reg <= {shift_reg[DATA_WIDTH-2:0], din[DATA_WIDTH-1]};
                dout <= shift_reg[DATA_WIDTH-1:DATA_WIDTH-SHIFT_VALUE];
                if (OVERFLOW_WARNING == 1) begin
                    if (shift_reg[DATA_WIDTH-1] == 1'b1) begin
                        warning <= 2'b11;
                    end
                    else if (shift_reg[DATA_WIDTH-1] == 1'b0) begin
                        if (shift_reg[DATA_WIDTH-2:0] == 2**DATA_WIDTH-1) begin
                            warning <= 2'b10;
                        end
                    end
                end
            end
        end
        else begin
            assign shift_out = {din[DATA_WIDTH-2:0], din[DATA_WIDTH-1]};
            assign dout = shift_out[DATA_WIDTH-1:DATA_WIDTH-SHIFT_VALUE];
            assign warning = 2'b00;
        end
    end
    else begin
        if (ASYNC == 0) begin
            always @(posedge clk) begin
                shift_reg <= {shift_reg[DATA_WIDTH-2:0], din[DATA_WIDTH-1]};
                dout <= shift_reg[DATA_WIDTH-1:DATA_WIDTH-SHIFT_VALUE];
                if (OVERFLOW_WARNING == 1) begin
                    if (shift_reg[DATA_WIDTH-1] == 2**DATA_WIDTH-1) begin
                        warning <= 2'b11;
                    end
                end
            end
        end
        else begin
            assign shift_out = {din[DATA_WIDTH-2:0], din[DATA_WIDTH-1]};
            assign dout = shift_out[DATA_WIDTH-1:DATA_WIDTH-SHIFT_VALUE];
            assign warning = 2'b00;
        end
    end
endmodule

