    reg[31:0] u_var; 
    wire[31:0] temp; 
    always @(posedge CLK) begin
        if (reset) begin
            x_var <= 0; 
            y_var <= 0; 
            u_var <= 0; 
        end
        else begin
            temp = x_var + (DXport * (Uinport - Yinport)); 
            if (temp >= Aport) begin
                Xoutport <= x_var; 
                Youtport <= y_var; 
                Uoutport <= u_var; 
            end
            else begin
                x_var <= temp; 
                y_var <= temp; 
                u_var <= temp; 
            end
        end
    end
endmodule

