module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [3:0] digit;
    always @(posedge clk) begin
        if(reset) begin
            digit <= 4'b0000;
        end
        else begin
            digit <= digit + 1;
        end
    end
    always @(*) begin
        case(digit)
            4'b0000: begin
                sseg = 8'b00000000;
                en = 4'b0001;
            end
            4'b0001: begin
                sseg = 8'b11110011;
                en = 4'b0010;
            end
            4'b0010: begin
                sseg = 8'b00100100;
                en = 4'b0100;
            end
            4'b0011: begin
                sseg = 8'b00001100;
                en = 4'b1000;
            end
            4'b0100: begin
                sseg = 8'b11000000;
                en = 4'b0001;
            end
            4'b0101: begin
                sseg = 8'b01000010;
                en = 4'b0010;
            end
            4'b0110: begin
                sseg = 8'b01001100;
                en = 4'b0100;
            end
            4'b0111: begin
                sseg = 8'b01000000;
                en = 4'b1000;
            end
            4'b1000: begin
                sseg = 8'b00000000;
                en = 4'b0001;
            end
            4'b1001: begin
                sseg = 8'b00001100;
                en = 4'b0010;
            end
            4'b1010: begin
                sseg = 8'b00000000;
                en = 4'b0100;
            end
            4'b1011: begin
                sseg = 8'b11110000;
                en = 4'b1000;
            end
            4'b1100: begin
                sseg = 8'b00000000;
                en = 4'b0001;
            end
            4'b1101: begin
                sseg = 8'b00000000;
                en = 4'b0010;
            end
            4'b1110: begin
                sseg = 8'b00000000;
                en = 4'b0100;
            end
            4'b1111: begin
                sseg = 8'b00000000;
                en = 4'b1000;
            end
