module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
reg [16:0] tmp;
    always @(data_i, shift_i) begin
        case(shift_i)
            2'b00: tmp <= {data_i[13:0], data_i[13]};
            2'b01: tmp <= {data_i[13:0], data_i[13], data_i[13]};
            2'b10: tmp <= {data_i[13:0], data_i[13], data_i[13], data_i[13]};
            2'b11: tmp <= {data_i[13:0], data_i[13], data_i[13], data_i[13], data_i[13]};
        endcase
    end
    assign data_o = {tmp[16], tmp[15:0]};
endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @(*) begin
        if(enable == 0) begin
            y = 8'b00000000;
        end
        else begin
            case(a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
        end
    end
endmodule

