	always @ (binary) begin
		for (int i = 0; i < 16; i = i + 1) begin
			reg[31 - i] = binary[15 - i] + 3;
		end
		reg = reg >> 1;
		b = reg[31:28];
		s = reg[27:24];
		g = reg[23:20];
		q = reg[19:16];
	end
endmodule

