module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg  updateclk;
reg  capture;
reg  update;
reg  mainclk;

always @ (captnupdt or shiftnld or clk) begin
    case (captnupdt & shiftnld)
        2'b10 : begin
            updateclk <= clk;
            capture <= 1'b1;
        end
        2'b11 : begin
            updateclk <= clk;
            capture <= 1'b1;
        end
        2'b01 : begin
            updateclk <= clk;
            capture <= 1'b0;
        end
        default : begin
            updateclk <= 1'b0;
            capture <= 1'b0;
        end
    endcase
end

assign mainclk = updateclk & clk;
assign update = updateclk & clk;
assign updateclk = updateclk & clk;
assign capture = capture & clk;

initial begin
    updateclk <= 1'b0;
    capture <= 1'b0;
    update <= 1'b0;
    mainclk <= 1'b0;
end

endmodule

