module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma;
	reg [31:0] undersampled_sigma;
	reg [31:0] delta;
	reg [31:0] deriv;

	always @(posedge clk or posedge rstn) begin
		if (rstn == 1'b1) begin
			sigma <= 32'b0;
			undersampled_sigma <= 32'b0;
			delta <= 32'b0;
			deriv <= 32'b0;
		end else begin
			if (sdi == 1'b1) begin
				if (ock == 1'b1) begin
					sigma <= sigma + 32'b1;
				end else begin
					sigma <= sigma - 32'b1;
				end
			end else begin
				if (uck == 1'b1) begin
					undersampled_sigma <= undersampled_sigma + 32'b1;
				end else begin
					undersampled_sigma <= undersampled_sigma - 32'b1;
				end
			end
			if (sdi == 1'b1) begin
				if (sigma >= 32'b1) begin
					delta <= 32'b1;
				end else begin
					delta <= 32'b0;
				end
			end else begin
				if (sigma <= 32'b0) begin
					delta <= 32'b1;
				end else begin
					delta <= 32'b0;
				end
			end
			if (sdi == 1'b1) begin
				if (sigma >= 32'b1) begin
					deriv <= undersampled_sigma - sigma;
				end else begin
					deriv <= sigma - undersampled_sigma;
				end
			end else begin
				if (sigma <= 32'b0) begin
					deriv <= undersampled_sigma - sigma;
				end else begin
					deriv <= sigma - undersampled_sigma;
				end
			end
		end
	end
	assign dout = signed_data ? (deriv >= 32'b0) ? (deriv) : (-deriv) : (deriv);
endmodule

