module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
parameter Zeros = {SIZE{1'b0}};

reg [SIZE-1:0]state;
reg [SIZE-1:0]toggle;

reg [N-1:0]gray_out;

parameter [N-1:0] initial_state = {N{1'b0}};

assign gray_out = state[0:N-1];

always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= Zeros;
	else
		state <= state + enable;
end

always @(state)
begin
	toggle[0] = 1'b1;
	toggle[1:N] = state[1:N] ^ state[0:N-1];
end

endmodule

