module dpram_async
#(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter CLEAR_ON_INIT = 1,
    parameter ENABLE_BYPASS = 1
)
(
    clk,
    rst,
    raddr,
    re,
    waddr,
    we,
    din,
    dout
);


input                           clk;
input                           rst;
input [ADDR_WIDTH-1:0]          raddr;
input                           re;
input [ADDR_WIDTH-1:0]          waddr;
input                           we;
input [DATA_WIDTH-1:0]          din;
output [DATA_WIDTH-1:0]         dout;
reg [DATA_WIDTH-1:0]            mem [0:2**ADDR_WIDTH-1];
reg [DATA_WIDTH-1:0]            dout_reg;

reg [ADDR_WIDTH-1:0]            raddr_reg;
reg [ADDR_WIDTH-1:0]            waddr_reg;
reg [DATA_WIDTH-1:0]            din_reg;

reg [ADDR_WIDTH-1:0]            raddr_reg_next;
reg [ADDR_WIDTH-1:0]            waddr_reg_next;
reg [DATA_WIDTH-1:0]            din_reg_next;

reg [ADDR_WIDTH-1:0]            dout_reg_next;

reg [ADDR_WIDTH-1:0]            dout_reg_next_bypass;

always @ (posedge clk)
begin
    if (rst)
    begin
        dout_reg <= 0;
        dout_reg_next <= 0;
        dout_reg_next_bypass <= 0;
    end
    else
    begin
        dout_reg <= dout_reg_next;
        dout_reg_next <= dout_reg_next_bypass;
    end
end

assign dout = dout_reg;

always @ (posedge clk)
begin
    if (rst)
    begin
        dout_reg_next <= 0;
        dout_reg_next_bypass <= 0;
    end
    else
    begin
        if (ENABLE_BYPASS)
        begin
            dout_reg_next_bypass <= din;
        end
        else
        begin
            dout_reg_next_bypass <= mem[raddr_reg];
        end
    end
end

always @ (posedge clk)
begin
    if (rst)
    begin
        dout_reg_next <= 0;
    end
    else
    begin
        if (re)
        begin
            dout_reg_next <= din;
        end
        else if (we)
        begin
            dout_reg_next <= mem[waddr_reg];
        end
    end
end

always @ (posedge clk)
begin
    if (rst)
    begin
        raddr_reg <= 0;
        waddr_reg <= 0;
        din_reg <= 0;
    end
    else
    begin
        raddr_reg <= raddr;
        waddr_reg <= waddr;
        din_reg <= din;
    end
end

always @ (posedge clk)
begin
    if (rst)
    begin
        raddr_reg_next <= 0;
        waddr_reg_next <= 0;
        din_reg_next <= 0;
    end
    else
    begin
        raddr_reg_next <= raddr_reg;
        waddr_reg_next <= waddr_reg;
        din_reg_next <= din_reg;
    end
end

always @ (posedge clk)
begin
    if (rst)
    begin
        mem <= 0;
    end
    else
    begin
        if (CLEAR_ON_INIT)
        begin
            mem <= 0;
        end
        else
        begin
            mem <= mem;
        end
    end
end

assign dout_reg_next_bypass = din_reg;

assign raddr_reg_next = raddr_reg;
assign waddr_reg_next = waddr_reg;
assign din_reg_next = din_reg;

endmodule

