module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
reg [23:0] r_rgb;
reg [23:0] r_count;
reg [1:0]  state;

always @(posedge clk) begin
  if (rst) begin
    r_rgb <= 0;
    r_count <= 0;
    state <= IDLE;
  end else begin
    case (state)
      IDLE: begin
        if (i_h_sync) begin
          r_rgb <= i_rgb;
          r_count <= 0;
          state <= READY;
        end
      end
      READY: begin
        if (i_h_sync) begin
          r_rgb <= i_rgb;
          r_count <= r_count + 1;
          if (r_count == i_ppfifo_size) begin
            state <= RELEASE;
          end
        end
      end
      RELEASE: begin
        o_ppfifo_stb <= 0;
        o_ppfifo_act <= 0;
        o_ppfifo_clk <= 0;
        state <= IDLE;
      end
    endcase
  end
end

assign o_ppfifo_clk = clk;
assign o_ppfifo_stb = i_data_en & (state == READY);
assign o_ppfifo_data = r_rgb;
assign o_ppfifo_act = i_ppfifo_rdy;

endmodule

