module hardcopyiv_pciehip_pciexp_dcram_rtry (
   wrclock,
   wren,
   wraddress,
   data,
   rdclock,
   rdaddress,
   q
   );

	input   wrclock; 
	input   wren; 
	input   [data_width - 1:0] data; 
	input   [addr_width - 1:0] wraddress; 
	input	rdclock;
	input   [addr_width - 1:0] rdaddress; 
	output  [data_width - 1:0] q;
parameter data_width = 16;
parameter addr_width = 16;
parameter ram_size = 1 << addr_width;

	reg [data_width - 1:0] wrdata;
	reg [addr_width - 1:0] wraddress;
	reg [data_width - 1:0] rddata;
	reg [addr_width - 1:0] rdaddress;

	always @(posedge wrclock) begin
		if (wren) begin
			wrdata <= data;
			wraddress <= wraddress;
		end
	end

	always @(posedge rdclock) begin
		if (wren) begin
			rddata <= q;
			rdaddress <= rdaddress;
		end
	end

	dcram #(
		.data_width(data_width),
		.addr_width(addr_width),
		.ram_size(ram_size)
	) ram (
		.q(q),
		.wrdata(wrdata),
		.wraddress(wraddress),
		.rddata(rddata),
		.rdaddress(rdaddress)
	);
endmodule

