module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter INSERT_REGISTER = 0;
 parameter DATA_WIDTH = 16;

  reg [DATA_WIDTH-1:0] o_dataout_reg;
  reg o_datain_stall_reg;
  reg o_dataout_valid_reg;

  always @(posedge clock or negedge resetn) begin
    if (!resetn) begin
      o_datain_stall_reg <= 1'b0;
      o_dataout_valid_reg <= 1'b0;
    end else begin
      o_datain_stall_reg <= o_datain_stall;
      o_dataout_valid_reg <= o_dataout_valid;
    end
  end

  always @(posedge clock or negedge resetn) begin
    if (!resetn) begin
      o_dataout <= 1'b0;
    end else begin
      if (o_datain_stall_reg) begin
        o_dataout <= 1'b0;
      end else begin
        o_dataout <= o_dataout_reg;
      end
    end
  end

  always @(posedge clock or negedge resetn) begin
    if (!resetn) begin
      o_dataout_reg <= 1'b0;
    end else begin
      if (o_datain_stall_reg) begin
        o_dataout_reg <= 1'b0;
      end else begin
        o_dataout_reg <= i_datain;
      end
    end
  end

  always @(posedge clock or negedge resetn) begin
    if (!resetn) begin
      o_datain_stall <= 1'b0;
    end else begin
      if (o_datain_stall_reg) begin
        o_datain_stall <= 1'b0;
      end else begin
        o_datain_stall <= i_dataout_stall;
      end
    end
  end

  assign o_datain_stall = o_datain_stall_reg;
  assign o_dataout_valid = o_dataout_valid_reg;
  assign o_dataout = o_dataout_reg;

endmodule

