module TopModule (
    input  clk,
    input  reset,
    output q (10 bits)
);
reg [9:0] counter;

always @(posedge clk) begin
    if (reset) begin
        counter <= 10'b0000000000;
    end else begin
        counter <= counter + 10'b0000000001;
    end
end

assign q = counter;

endmodule

