module TopModule (
    input  in (4 bits),
    output out_and,
    output out_or,
    output out_xor
);
    wire and_in0, and_in1, and_in2, and_in3;
    wire or_in0, or_in1, or_in2, or_in3;
    wire xor_in0, xor_in1, xor_in2, xor_in3;

    and and0 (and_in0, in[0], in[1], in[2], in[3]);
    or or0 (or_in0, in[0], in[1], in[2], in[3]);
    xor xor0 (xor_in0, in[0], in[1], in[2], in[3]);
    and and1 (and_in1, and_in0, and_in1, and_in2, and_in3);
    or or1 (or_in1, or_in0, or_in1, or_in2, or_in3);
    xor xor1 (xor_in1, xor_in0, xor_in1, xor_in2, xor_in3);
    and and2 (and_in2, and_in0, and_in1, and_in2, and_in3);
    or or2 (or_in2, or_in0, or_in1, or_in2, or_in3);
    xor xor2 (xor_in2, xor_in0, xor_in1, xor_in2, xor_in3);
    and and3 (and_in3, and_in0, and_in1, and_in2, and_in3);
    or or3 (or_in3, or_in0, or_in1, or_in2, or_in3);
    xor xor3 (xor_in3, xor_in0, xor_in1, xor_in2, xor_in3);

    assign out_and = and_in3;
    assign out_or = or_in3;
    assign out_xor = xor_in3;

endmodule

