module TopModule (
    input  clk,
    input  x,
    output z
);
reg [1:0] d0, d1, d2;
    wire [1:0] xor0, and0, or0, nor0;
    xor xor0(xor0, x, d0);
    and and0(and0, d0, d1);
    or or0(or0, d1, d2);
    nor nor0(nor0, xor0, and0, or0);
    always @(posedge clk) begin
        d0 <= ~d1;
        d1 <= ~d2;
        d2 <= xor0;
    end
endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out,
    output out_n
);
wire and1_out;
    wire and2_out;
    wire or1_out;

    and and1 (and1_out, a, b);
    and and2 (and2_out, c, d);
    or or1 (or1_out, and1_out, and2_out);
    not not1 (out_n, or1_out);
    assign out = or1_out;

endmodule

