module TopModule (
    input  clk,
    input  load,
    input  data (10 bits),
    output tc
);
reg [9:0] counter;
    wire tc;

    always @(posedge clk) begin
        if (load) begin
            counter <= data;
        end else begin
            if (counter == 0) begin
                tc <= 1'b1;
            end else begin
                tc <= 1'b0;
            end
            counter <= counter - 1;
        end
    end

endmodule

