module TopModule(
    input  clk,
    input  enable,
    input  S,
    input  A,
    input  B,
    input  C,
    output Z
);
reg [7:0] Q;
    assign Z = Q[0];
    always @(posedge clk) begin
        if(enable) begin
            Q <= {Q[7:1],S};
        end
    end
    assign Q[0] = A & B & C;
    assign Q[1] = A & B & ~C;
    assign Q[2] = A & ~B & C;
    assign Q[3] = A & ~B & ~C;
    assign Q[4] = ~A & B & C;
    assign Q[5] = ~A & B & ~C;
    assign Q[6] = ~A & ~B & C;
    assign Q[7] = ~A & ~B & ~C;
endmodule

module TopModule (
    input  clk,
    input  reset,
    output q (5 bits)
);
reg [4:0] lfsr;

    always @(posedge clk) begin
        if (reset) begin
            lfsr <= 5'b11111;
        end else begin
            lfsr[4] <= lfsr[3] ^ lfsr[0];
            lfsr[3] <= lfsr[2] ^ lfsr[0];
            lfsr[2] <= lfsr[1] ^ lfsr[0];
            lfsr[1] <= lfsr[0];
            lfsr[0] <= 1'b0;
        end
    end

    assign q = lfsr;

endmodule

module TopModule (
    input  a,
    input  b,
    output out_and,
    output out_or,
    output out_xor,
    output out_nand,
    output out_nor,
    output out_xnor,
    output out_anotb
);
assign out_and = a & b;
    assign out_or = a | b;
    assign out_xor = a ^ b;
    assign out_nand = a & ~b;
    assign out_nor = a | ~b;
    assign out_xnor = a ^ ~b;
    assign out_anotb = a & ~b;
endmodule

module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);
localparam [2:0] A = 3'b000;
    localparam [2:0] B = 3'b001;
    localparam [2:0] C = 3'b010;
    localparam [2:0] D = 3'b011;
    localparam [2:0] E = 3'b100;
    localparam [2:0] F = 3'b101;
    localparam [2:0] G = 3'b110;
    localparam [2:0] H = 3'b111;

    reg [2:0] state = A;
    wire [2:0] next_state;

    always @(posedge clk) begin
        if (areset) begin
            state <= A;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            A: begin
                if (x == 1'b0) begin
                    next_state = A;
                end else begin
                    next_state = B;
                end
            end
            B: begin
                if (x == 1'b0) begin
                    next_state = B;
                end else begin
                    next_state = B;
                end
            end
            default: begin
                next_state = state;
            end
        endcase
    end

    assign z = state[2];

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);
reg [1:0] state;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
        end else begin
            state <= state + 1;
        end
    end
    assign z = ~x;
endmodule

