module TopModule (
    input  y (6 bits),
    input  w,
    output Y1,
    output Y3
);
reg [5:0] y;
    always @ (y or w)
        case (y[5:0])
            6'b000001: y <= 6'b000010;
            6'b000010: y <= 6'b000100;
            6'b000100: y <= 6'b001000;
            6'b001000: y <= 6'b010000;
            6'b010000: y <= 6'b100000;
            default: y <= 6'b000001;
        endcase
    assign Y1 = y[1];
    assign Y3 = y[3];
endmodule

module TopModule (
    input  in            (100 bits),
    output out_both      (100 bits),
    output out_any       (100 bits),
    output out_different (100 bits)
);
    assign out_both[99] = 1'b0;
    assign out_any[99]  = 1'b0;
    assign out_different[99] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 100; i = i + 1) begin
            assign out_both[i] = in[i] & in[i+1];
            assign out_any[i] = in[i] | in[i+1];
            assign out_different[i] = in[i] ^ in[i+1];
        end
    endgenerate
endmodule

module TopModule (
    input  c,
    input  d,
    output mux_in (4 bits)
);
    wire a,b;
    assign mux_in[0] = a;
    assign mux_in[1] = b;
    assign mux_in[2] = a;
    assign mux_in[3] = b;
    assign a = c & d;
    assign b = c | d;
endmodule

module TopModule (
    input  in            (4 bits),
    output out_both      (4 bits),
    output out_any       (4 bits),
    output out_different (4 bits)
);
    assign out_both[0] = in[0] & in[1];
    assign out_both[1] = in[1] & in[2];
    assign out_both[2] = in[2] & in[3];
    assign out_both[3] = in[3] & in[0];

    assign out_any[0] = in[0] | in[1];
    assign out_any[1] = in[1] | in[2];
    assign out_any[2] = in[2] | in[3];
    assign out_any[3] = in[3] | in[0];

    assign out_different[0] = in[0] ^ in[1];
    assign out_different[1] = in[1] ^ in[2];
    assign out_different[2] = in[2] ^ in[3];
    assign out_different[3] = in[3] ^ in[0];

endmodule

module TopModule (
    input  clk,
    input  reset,
    output shift_ena
);
reg [3:0] shift_ena_counter;
    always @(posedge clk) begin
        if (reset) begin
            shift_ena_counter <= 4'b0000;
        end else begin
            if (shift_ena_counter == 4'b0001) begin
                shift_ena_counter <= 4'b0000;
            end else begin
                shift_ena_counter <= shift_ena_counter + 1;
            end
        end
    end
    assign shift_ena = shift_ena_counter == 4'b0001 ? 1'b1 : 1'b0;
endmodule

module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);
