module TopModule (
    input  clk,
    input  areset,
    input  in,
    output out
);
reg [1:0] state = 2'b10;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b10;
        end else begin
            case (state)
                2'b10: begin
                    state <= 2'b11;
                end
                2'b11: begin
                    state <= 2'b00;
                end
                2'b00: begin
                    state <= 2'b01;
                end
                default: begin
                    state <= 2'b10;
                end
            endcase
        end
    end
    assign out = state[0];
endmodule

module TopModule (
    input  clk,
    input  areset,
    input  j,
    input  k,
    output out
);
parameter [1:0] OFF = 2'b00;
parameter [1:0] ON  = 2'b01;

reg [1:0] state = OFF;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        state <= OFF;
    end else begin
        case (state)
            OFF: begin
                if (j == 0) begin
                    state <= OFF;
                end else begin
                    state <= ON;
                end
            end
            ON: begin
                if (k == 0) begin
                    state <= ON;
                end else begin
                    state <= OFF;
                end
            end
        endcase
    end
end

assign out = state;

endmodule

