module TopModule (
      input do_sub,
      input [7:0] a,
      input [7:0] b,
      output reg [7:0] out,
      output reg result_is_zero
  );

      always @(*) begin
          case (do_sub)
            0: out = a+b;
            1: out = a-b;
          endcase

          if (~out)
              result_is_zero = 1;
      end

  endmodule

module TopModule (
    input  clk,
    input  load,
    input  data (512 bits),
    output q    (512 bits)
);
reg [511:0] q;
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            q[0] <= q[1] & ~q[2];
            q[511] <= ~q[510] & q[511];
            for (int i = 1; i < 511; i = i + 1) begin
                q[i] <= q[i-1] & ~q[i] & q[i+1];
            end
        end
    end
endmodule

