module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output walk_left,
    output walk_right
);
reg [1:0] state;
    wire [1:0] next_state;

    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            2'b00: begin
                next_state = 2'b01;
                walk_left  = 1'b0;
                walk_right = 1'b0;
            end
            2'b01: begin
                next_state = 2'b10;
                walk_left  = 1'b1;
                walk_right = 1'b0;
            end
            2'b10: begin
                next_state = 2'b11;
                walk_left  = 1'b0;
                walk_right = 1'b1;
            end
            2'b11: begin
                next_state = 2'b00;
                walk_left  = 1'b1;
                walk_right = 1'b0;
            end
        endcase
    end

    assign walk_left  = state[0];
    assign walk_right = state[1];

endmodule

