            state <= 3'b000;
        end else begin
            case (state)
                3'b000: begin
                    if (r[0] == 1'b1) begin
                        state <= 3'b001;
                    end else if (r[1] == 1'b1) begin
                        state <= 3'b010;
                    end else if (r[2] == 1'b1) begin
                        state <= 3'b011;
                    end
                end
                3'b001: begin
                    state <= 3'b000;
                end
                3'b010: begin
                    state <= 3'b000;
                end
                3'b011: begin
                    state <= 3'b000;
                end
            endcase
        end
    end
    assign g[0] = state == 3'b000;
    assign g[1] = state == 3'b001;
    assign g[2] = state == 3'b010;
endmodule

