module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state (10 bits),
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);
reg [9:0] state_reg;
    assign B3_next = state_reg[9];
    assign S_next = state_reg[8];
    assign S1_next = state_reg[7];
    assign Count_next = state_reg[6];
    assign Wait_next = state_reg[5];
    assign done = state_reg[4];
    assign counting = state_reg[3];
    assign shift_ena = state_reg[2];
    always @(*) begin
        case (state)
            10'b0000000001: begin
                state_reg <= 10'b0000000010;
            end
            10'b0000000010: begin
                state_reg <= 10'b0000000100;
            end
            10'b0000000100: begin
                state_reg <= 10'b0000001000;
            end
            10'b0000001000: begin
                state_reg <= 10'b0000010000;
            end
            10'b0000010000: begin
                state_reg <= 10'b0000100000;
            end
            10'b0000100000: begin
                state_reg <= 10'b0001000000;
            end
            10'b0001000000: begin
                state_reg <= 10'b0010000000;
            end
            10'b0010000000: begin
                state_reg <= 10'b0100000000;
            end
            10'b0100000000: begin
                state_reg <= 10'b1000000000;
            end
            default: begin
                state_reg <= 10'b0000000001;
            end
        endcase
    end
endmodule

